def _snapshot(
    *,
    python: str = "3.12",
    tag: str = "v3.12.1",
    revision: str = "a" * 40,
    header: tuple[str, ...] = FIXTURE_HEADER,
    entries: tuple[str, ...] = FETCHED_ENTRIES,
) -> gen.SourceSnapshot:
    payload = ("\n".join(header) + "\n").encode("utf-8")
    return gen.SourceSnapshot(
        python=python,
        tag=tag,
        revision=revision,
        header_object=gen._git_blob_id(payload),
        header_lines=header,
        lib_object="b" * 40,
        lib_entries=entries,
    )


def _write_pins(path: Path, rows: dict[str, tuple[str, str]]) -> None:
    lines = ['schema = "molt.cpython-regrtest-sources.v1"']
    for python, (tag, revision) in rows.items():
        lines += [
            "",
            "[[source]]",
            f'python = "{python}"',
            f'revision = "{revision}"',
            f'tag = "{tag}"',
            f'git_url = "{CPYTHON_URL}"',
        ]
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


