def test_parse_stdlib_module_names_reads_the_array() -> None:
    shuffled = (*FIXTURE_HEADER[:4], '"xml",', *FIXTURE_HEADER[4:9], "};")
    assert gen.parse_stdlib_module_names(shuffled) == FIXTURE_NAMES


@pytest.mark.parametrize(
    ("lines", "message"),
    [
        (FIXTURE_HEADER[:3], "no 'static const char"),
        ((*FIXTURE_HEADER[:5], "#ifdef MS_WINDOWS", "};"), "unexpected array line"),
        (FIXTURE_HEADER[:-1], "not closed"),
        ((*FIXTURE_HEADER[:4], "};"), "empty"),
        ((*FIXTURE_HEADER[:5], '"abc",', "};"), "duplicate module names"),
    ],
)
def test_parse_stdlib_module_names_fails_closed(
    lines: tuple[str, ...], message: str
) -> None:
    with pytest.raises(ValueError, match=message):
        gen.parse_stdlib_module_names(lines)


