# --- Refresh ---------------------------------------------------------------


def test_refresh_fails_closed_when_content_at_a_pinned_revision_changes(
    fixture_authority: Path,
) -> None:
    before = gen.SNAPSHOT_PATH.read_bytes()
    tampered = _snapshot(entries=("abc.py", "abc_fake.py"))

    with pytest.raises(RuntimeError, match="does not match the receipt") as raised:
        gen.refresh_sources(fetch=lambda pin: tampered)

    assert "nothing was written" in str(raised.value)
    assert gen.SNAPSHOT_PATH.read_bytes() == before


def test_refresh_replaces_a_moved_pin_and_keeps_an_unchanged_one(
    fixture_authority: Path, capsys
) -> None:
    before = gen.SNAPSHOT_PATH.read_bytes()
    assert gen.refresh_sources(fetch=lambda pin: _snapshot()) == 0
    assert gen.SNAPSHOT_PATH.read_bytes() == before
    assert "current" in capsys.readouterr().out

    _write_pins(gen.PINS_PATH, {"3.12": ("v3.12.2", "d" * 40)})
    moved = _snapshot(tag="v3.12.2", revision="d" * 40, entries=("abc.py",))
    assert gen.refresh_sources(fetch=lambda pin: moved) == 0
    assert gen.load_snapshot(gen.SNAPSHOT_PATH) == {"3.12": moved}


def test_main_routes_refresh_and_rejects_mixed_modes(monkeypatch) -> None:
    calls: list[str] = []
    monkeypatch.setattr(gen, "refresh_sources", lambda: calls.append("refresh") or 0)

    assert gen.main(["--refresh-sources"]) == 0
    assert calls == ["refresh"]
    with pytest.raises(SystemExit) as raised:
        gen.main(["--refresh-sources", "--check"])
    assert raised.value.code == 2


def test_git_failure_fails_closed_through_the_memory_guard(
    monkeypatch, tmp_path: Path
) -> None:
    captured: dict[str, object] = {}

    def fake_guarded_completed_process(cmd, **kwargs):
        captured.update(cmd=cmd, **kwargs)
        return subprocess.CompletedProcess(cmd, 128, stdout=b"", stderr=b"denied")

    monkeypatch.setattr(
        gen.harness_memory_guard,
        "guarded_completed_process",
        fake_guarded_completed_process,
    )

    with pytest.raises(RuntimeError, match="exit code 128: denied"):
        gen._git(["fetch", "origin"], cwd=tmp_path)

    assert captured["cmd"] == ["git", "fetch", "origin"]
    assert captured["prefix"] == "MOLT_GENERATOR"
    assert captured["text"] is False
    assert captured["env"]["GIT_TERMINAL_PROMPT"] == "0"


def _fixture_remote(root: Path) -> tuple[Path, str, str]:
    """A tagged repository shaped like CPython, served like GitHub serves it."""
    env = {
        **os.environ,
        "GIT_CONFIG_GLOBAL": os.devnull,
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_AUTHOR_NAME": "fixture",
        "GIT_AUTHOR_EMAIL": "fixture@example.invalid",
        "GIT_COMMITTER_NAME": "fixture",
        "GIT_COMMITTER_EMAIL": "fixture@example.invalid",
    }

    def git(*args: str) -> str:
        command = ["git", "-C", str(root), *args]
        return run_guarded_test_process(command, env=env, check=True).stdout.strip()

    files = {
        "Python/stdlib_module_names.h": "\n".join(FIXTURE_HEADER) + "\n",
        "README.rst": "not part of the inputs\n",
        **{
            f"Lib/{entry}": "# fixture\n"
            for entry in FIXTURE_ENTRIES
            if not entry.endswith("/")
        },
    }
    for relative, text in files.items():
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    git("init", "--quiet")
    git("config", "uploadpack.allowFilter", "true")
    git("config", "uploadpack.allowAnySHA1InWant", "true")
    git("add", "--all")
    git("commit", "--quiet", "--message", "fixture")
    git("tag", "--annotate", "--message", "fixture", "v3.12.1")
    return root, git("rev-parse", "HEAD"), git("rev-parse", "HEAD:Lib")


def test_fetch_reads_a_pinned_tag_without_blobs(tmp_path: Path) -> None:
    remote, revision, lib_object = _fixture_remote(tmp_path / "cpython")
    pin = gen.CPythonSource(
        python="3.12", revision=revision, tag="v3.12.1", git_url=remote.as_uri()
    )

    snapshot = gen.fetch_pinned_source(pin)

    assert snapshot == gen.SourceSnapshot(
        python="3.12",
        tag="v3.12.1",
        revision=revision,
        header_object=_snapshot().header_object,
        header_lines=FIXTURE_HEADER,
        lib_object=lib_object,
        lib_entries=FETCHED_ENTRIES,
    )
    assert gen.derive_version_data(FIXTURE_NAMES, snapshot.lib_entries) == (
        EXPECTED_PACKAGES,
        EXPECTED_PY_MODULES,
        EXPECTED_PY_PACKAGES,
    )

    moved = gen.CPythonSource(
        python="3.12", revision="f" * 40, tag="v3.12.1", git_url=remote.as_uri()
    )
    with pytest.raises(RuntimeError, match="resolves to"):
        gen.fetch_pinned_source(moved)


# --- Rendering -------------------------------------------------------------


def _version_data(modules, packages, py_modules, py_packages) -> gen.VersionData:
    return gen.VersionData(
        tag="v3.12.1",
        revision="a" * 40,
        modules=modules,
        packages=packages,
        py_modules=py_modules,
        py_packages=py_packages,
    )


def test_render_outputs_split_version_data_and_preserve_facade(tmp_path: Path) -> None:
    output = tmp_path / "stdlib_module_union.py"
    rendered = gen.render_outputs(
        output=output,
        versions=("3.12", "3.13"),
        data={
            "3.12": _version_data(
                ("abc", "sys"),
                ("asyncio",),
                ("abc", "asyncio.base_events"),
                ("asyncio",),
            ),
            "3.13": _version_data(
                ("abc", "annotationlib"),
                ("asyncio", "pathlib"),
                ("abc", "pathlib._local"),
                ("asyncio", "pathlib"),
            ),
        },
    )

    for path, text in rendered.items():
        path.write_text(text, encoding="utf-8")

    namespace = runpy.run_path(str(output))

    assert namespace["BASELINE_PYTHON_VERSIONS"] == ("3.12", "3.13")
    assert namespace["STDLIB_MODULES_BY_VERSION"] == {
        "3.12": ("abc", "sys"),
        "3.13": ("abc", "annotationlib"),
    }
    assert namespace["STDLIB_MODULE_UNION"] == ("abc", "annotationlib", "sys")
    assert namespace["STDLIB_PACKAGE_UNION"] == ("asyncio", "pathlib")
    assert namespace["STDLIB_PY_SUBMODULE_UNION"] == (
        "asyncio.base_events",
        "pathlib._local",
    )
    version_module = (tmp_path / "stdlib_module_union_3_12.py").read_text(
        encoding="utf-8"
    )
    assert f"CPython source: v3.12.1 ({'a' * 40})" in version_module
    assert (tmp_path / "stdlib_module_union_3_13.py").exists()
    facade = output.read_text(encoding="utf-8")
    assert "_load_version_data" in facade
    assert "STDLIB_MODULES = (" not in facade


def test_generated_outputs_derive_every_supported_version(
    fixture_authority: Path,
) -> None:
    rendered = gen.generated_outputs()

    output = fixture_authority / "stdlib_module_union.py"
    assert set(rendered) == {output, fixture_authority / "stdlib_module_union_3_12.py"}
    assert not any(path.exists() for path in rendered)
    for path, text in rendered.items():
        path.write_text(text, encoding="utf-8")
    namespace = runpy.run_path(str(output))
    assert namespace["STDLIB_MODULE_UNION"] == FIXTURE_NAMES
    assert namespace["STDLIB_PACKAGE_UNION"] == EXPECTED_PACKAGES
    assert namespace["STDLIB_PY_MODULE_UNION"] == EXPECTED_PY_MODULES
    assert namespace["STDLIB_PY_PACKAGE_UNION"] == EXPECTED_PY_PACKAGES


def test_generated_outputs_fail_closed_on_a_retired_version_module(
    monkeypatch, tmp_path: Path
) -> None:
    output = tmp_path / "stdlib_module_union.py"
    monkeypatch.setattr(gen, "OUT_PATH", output)
    retired = tmp_path / "stdlib_module_union_3_11.py"
    retired.write_text(f'"""\n{gen.GENERATED_DATA_MARKER}\n"""\n', encoding="utf-8")
    hand_written = tmp_path / "stdlib_module_union_notes.py"
    hand_written.write_text("# not generated\n", encoding="utf-8")

    def unreachable(versions):
        raise AssertionError("retired outputs must fail before reading sources")

    monkeypatch.setattr(gen, "pinned_snapshots", unreachable)

    with pytest.raises(RuntimeError, match="no longer renders") as raised:
        gen.generated_outputs()

    assert str(retired) in str(raised.value)
    assert str(hand_written) not in str(raised.value)
    assert retired.exists()
